int sys_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct task_struct *tsk;

    tsk = find_task_by_vpid(upid);
    if (!tsk) {
        return -ECHILD;
    }

    if (invalid_waitid_flags(options)) {
        return -EINVAL;
    }

    if (infop) {
        if (copy_siginfo_to_user(infop, tsk->pending.info)) {
            return -EFAULT;
        }
    }

    if (ru) {
        if (copy_rusage_to_user(ru, &tsk->rusage)) {
            return -EFAULT;
        }
    }

    return 0;
}

#include <sys/types.h>
#include <sys/wait.h>
#include <sys/resource.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>

int handle_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    pid_t pid;
    int status = 0;
    struct rusage rusage_data;

    if (which != P_ALL && which != P_PID && which != P_PGID) {
        return -EINVAL;
    }

    if (which == P_PID) {
        pid = waitid(WNOWAIT | WSTOPPED, upid, NULL, options, &rusage_data);
    } else if (which == P_PGID) {
        pid = waitid(WNOWAIT | WSTOPPED, -upid, NULL, options, &rusage_data);
    } else {
        pid = waitid(WNOWAIT | WSTOPPED, 0, NULL, options, &rusage_data);
    }

    if (pid < 0) {
        return -errno;
    }

    if (infop) {
        if (copy_to_user(infop, &rusage_data, sizeof(struct siginfo)) != 0) {
            return -EFAULT;
        }
    }

    if (ru) {
        if (copy_to_user(ru, &rusage_data, sizeof(struct rusage)) != 0) {
            return -EFAULT;
        }
    }

    return 0;
}

