int handle_waitid(int which, pid_t upid, struct siginfo __user *infop, int options, struct rusage __user *ru) {
    struct siginfo ksiginfo;
    struct rusage kru;
    int result;

    // Clear the kernel structures
    memset(&ksiginfo, 0, sizeof(ksiginfo));
    memset(&kru, 0, sizeof(kru));

    // Perform the waitid system call
    result = waitid(which, upid, &ksiginfo, options, ru ? &kru : NULL);

    if (result < 0) {
        // If waitid failed, return the error code
        return -errno;
    }

    // Copy the siginfo structure to user space if provided
    if (infop && copy_to_user(infop, &ksiginfo, sizeof(ksiginfo)) != 0) {
        return -EFAULT;
    }

    // Copy the rusage structure to user space if requested
    if (ru && copy_to_user(ru, &kru, sizeof(kru)) != 0) {
        return -EFAULT;
    }

    return 0;
}

